from PIL import Image, ImageOps, ImageDraw
im = Image.open('/app/radiograph.jpg').convert('L')
# gridded zooms with 20px minor grid in ORIGINAL coords
zooms = {
 'GQ1_ur_molars': (720, 360, 1030, 640),
 'GQ6_lr_molars': (640, 500, 1040, 820),
}
for name,(x1,y1,x2,y2) in zooms.items():
    c = im.crop((x1,y1,x2,y2)).convert('RGB')
    s = 3
    c = c.resize((int(c.width*s), int(c.height*s)), Image.LANCZOS)
    d = ImageDraw.Draw(c)
    for gx in range(x1, x2+1, 20):
        X = (gx-x1)*s
        col = (255,0,0) if gx%100==0 else (0,255,0)
        d.line([(X,0),(X,c.height)], fill=col, width=1)
        if gx%100==0: d.text((X+2,2), str(gx), fill=(255,255,0))
    for gy in range(y1, y2+1, 20):
        Y = (gy-y1)*s
        col = (255,0,0) if gy%100==0 else (0,255,0)
        d.line([(0,Y),(c.width,Y)], fill=col, width=1)
        if gy%100==0: d.text((2,Y+2), str(gy), fill=(255,255,0))
    c.save(f'/tmp/{name}.png')
    print(name, c.size)
