out = Image.open('/tmp/flat_full.png')
def gridded(img, name, box, s, step=20):
    x1,y1,x2,y2 = box
    c = img.crop(box).convert('RGB')
    c = c.resize((int((x2-x1)*s), int((y2-y1)*s)), Image.LANCZOS)
    d = ImageDraw.Draw(c)
    for gx in range(x1, x2+1, step):
        X=(gx-x1)*s; col=(255,60,60) if gx%100==0 else (0,230,0)
        d.line([(X,0),(X,c.height)],fill=col,width=1)
        if gx%100==0: d.text((X+2,2),str(gx),fill=(255,220,0))
    for gy in range(y1, y2+1, step):
        Y=(gy-y1)*s; col=(255,60,60) if gy%100==0 else (0,230,0)
        d.line([(0,Y),(c.width,Y)],fill=col,width=1)
        if gy%100==0: d.text((2,Y+2),str(gy),fill=(255,220,0))
    c.save(f'/tmp/{name}.png'); print(name, c.size)
gridded(out, 'GA_upper_ant', (1080, 360, 1560, 640), 2.2)
